function courseCard(c){return `<article class="card course-card" data-course="${c.name}" data-status="${c.status||'catalog'}"><div class="course-thumb ${c.thumb}">${icon(c.symbol)}</div><div class="course-info"><div class="course-meta">${c.meta}</div><h3>${c.name}</h3><div class="course-bottom"><span>${c.done}</span><b>${c.progress}%</b></div><div class="progress-line"><i style="width:${c.progress}%"></i></div><div class="course-bottom"><span>${c.teacher}</span><span>${c.time}</span></div></div></article>`}
