function renderTests(){return `${head('ПРОВЕРКА ЗНАНИЙ','Тесты и экзамены','Пройдите тест, разберите слабые темы и вернитесь к нужным урокам.')}<div class="banner">${icon('spark')}Unit Test подбирает новый набор вопросов после каждого повтора. Лучший результат сохраняется.</div><div class="content-section"><div class="section-head"><h2>Доступно сейчас</h2><span class="pill">3 теста</span></div><div class="course-grid">${[['Тест юнита: Кариес и реставрация','20 вопросов · 25 мин','Открыт','86%'],['Мини-тест: Анестетики','6 вопросов · 8 мин','Повтор','60%'],['Входная диагностика','32 вопроса · 40 мин','Завершён','74%']].map((t,i)=>`<article class="card form-card"><div class="course-meta">${i===0?'UNIT TEST':i===1?'ПОВТОР ТЕМЫ':'ДИАГНОСТИКА'}</div><h3>${t[0]}</h3><p class="subhead">${t[1]} · ${i===0?'Вопросы из банка перемешаны':'Лучший результат сохраняется'}</p><div class="section-head" style="margin:14px 0 0"><span class="status ${i===1?'warning':''}">${t[2]} · ${t[3]}</span><button class="btn ${i===2?'btn-outline':'btn-primary'} btn-sm" data-action="start-test" data-test="${t[0]}">${i===2?'Разбор':'Начать'} ${icon('chevron')}</button></div></article>`).join('')}</div></div><div class="content-section"><div class="section-head"><h2>Экзамены курса</h2><span class="pill">Открываются после юнит-тестов</span></div><div class="card approval-card"><span class="stat-icon">${icon('award')}</span><div class="approval-copy"><h3>Итоговый экзамен · Терапия 1</h3><p>Сдайте Unit Test с результатом 85% или выше, чтобы открыть экзамен и запросить практический допуск.</p></div><span class="status neutral">Закрыт</span></div></div>`}
