const roleRoutes={learner:['dashboard','courses','library','tests','quiz','webinars','mentoring','messages','review','certificates','clinic','profile','settings','course','search'],mentor:['dashboard','courses','library','tests','quiz','webinars','mentoring','messages','review','certificates','clinic','team','analytics','profile','settings','course','search'],admin:['dashboard','courses','library','tests','webinars','mentoring','messages','review','studio','team','analytics','platform','clinic','certificates','profile','settings','course','search'],chief:['dashboard','courses','library','tests','webinars','mentoring','messages','review','studio','team','analytics','approvals','platform','clinic','certificates','profile','settings','course','search']};
roleRoutes.learner.push('analytics');
for(const r of Object.keys(roleRoutes))roleRoutes[r].push('lesson');
if(!roleInfo[app.role])app.role='learner';
try{const savedRole=localStorage.getItem('da-role');if(roleInfo[savedRole])app.role=savedRole;app.doctorTrack=JSON.parse(localStorage.getItem('da-doctor-track')||'null')}catch{app.doctorTrack=null}
function persistRole(){try{localStorage.setItem('da-role',app.role);if(app.doctorTrack)localStorage.setItem('da-doctor-track',JSON.stringify(app.doctorTrack));localStorage.setItem('da-account-profile',JSON.stringify(app.profile))}catch{}}
function roleDashboard(){if(app.role==='learner')return renderDashboard();if(app.role==='mentor')return `${head('КАБИНЕТ НАСТАВНИКА','Мои ученики','Отслеживайте прогресс подопечных, разбирайте вопросы и подтверждайте готовность к практике.','<button class="btn btn-outline" data-page="messages">Сообщения</button>')}<div class="dashboard-banner"><span class="role-pill">ВРАЧ · НАСТАВНИК</span><h3>Ваш учебный и наставнический профиль объединены</h3><p>Вы можете продолжать собственное обучение и переключаться между курсами и учениками.</p></div><div class="stats-row">${stat('Мои ученики','6','2 ждут обратной связи','users')}${stat('Средний прогресс','74%','За текущий поток','chart')}${stat('Заявки на допуск','3','Нужна оценка','check')}${stat('Вопросы','4','Непрочитанные','message')}</div><div class="content-section"><div class="section-head"><h2>Ученики</h2><button class="text-btn" data-page="team">Открыть список</button></div><div class="card table-card"><div class="table-head"><span>Ученик</span><span>Направление</span><span>Прогресс</span><span>Действие</span></div>${people.filter(p=>p[1]==='Стажёр').map(p=>`<div class="table-row"><span class="person-name">${p[0]}</span><span>${p[2]}</span><span>${p[3]}% · ${p[4]}</span><button class="btn btn-outline btn-sm" data-page="team">Профиль</button></div>`).join('')}</div></div><div class="content-section"><button class="btn btn-primary" data-page="approvals">Проверить заявки на практику</button> <button class="btn btn-outline" data-page="courses">Продолжить своё обучение</button></div>`;return `${head(app.role==='chief'?'РУКОВОДСТВО КЛИНИКОЙ':'УПРАВЛЕНИЕ ПЛАТФОРМОЙ',app.role==='chief'?'Панель главного врача':'Панель администратора',app.role==='chief'?'Полный обзор обучения, сотрудников, допусков и показателей клиники.':'Управляйте пользователями, клиниками, учебными материалами и качеством данных.')}<div class="dashboard-banner"><span class="role-pill">${roleInfo[app.role].label.toUpperCase()}</span><h3>${app.role==='chief'?'Контроль прогресса и клинических допусков':'Контроль платформы и учебного контента'}</h3><p>${app.role==='chief'?'Доступны персональные данные учеников клиники, результаты, заявки на ассистирование и решения по допускам.':'Управляйте каталогом организаций, пользователями, учебными материалами, аналитикой и исправлениями данных.'}</p></div><div class="stats-row">${stat('Ученики','42','6 требуют внимания','users')}${stat('Средний прогресс','71%','По активным курсам','chart')}${stat('Заявки на допуск','3','Ожидают решения','check')}${stat('Материалы','128','4 черновика на проверке','file')}</div><div class="content-section"><div class="section-head"><h2>Рабочие разделы</h2></div><div class="course-grid"><article class="card form-card"><h3>Пользователи и прогресс</h3><p>Профили, группы, назначение обучения и динамика результатов.</p><button class="btn btn-outline btn-sm" data-page="team">Открыть команду</button></article><article class="card form-card"><h3>Допуски и заявки</h3><p>Заявки на ассистирование, оценки наставников и решения руководителя.</p><button class="btn btn-outline btn-sm" data-page="approvals">Рассмотреть заявки</button></article><article class="card form-card"><h3>Клиники и данные</h3><p>Организации, реквизиты, публичные карточки и исправления.</p><button class="btn btn-outline btn-sm" data-page="platform">Управлять клиниками</button></article><article class="card form-card"><h3>Учебная аналитика</h3><p>Успеваемость, завершение курсов и активность команд.</p><button class="btn btn-outline btn-sm" data-page="analytics">Открыть аналитику</button></article></div></div>`}
const _renderPageForRoles=renderPage;
renderPage=function(){const allowed=roleRoutes[app.role]||roleRoutes.learner;if(!allowed.includes(app.page))app.page=roleInfo[app.role]?.home||'dashboard';if(app.page==='dashboard'&&app.role!=='learner'){$('#crumbSection').textContent='Управление';$('#crumbPage').textContent=app.role==='chief'?'Главный врач':roleInfo[app.role].label;$$('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page==='dashboard'));$('#page').innerHTML=roleDashboard()}else _renderPageForRoles();$$('.nav-item[data-page]').forEach(b=>{b.hidden=!allowed.includes(b.dataset.page)});$$('.nav-label').forEach(label=>{const nav=label.nextElementSibling;if(nav?.classList.contains('nav-list'))label.hidden=!Array.from(nav.querySelectorAll('.nav-item')).some(b=>!b.hidden)});if($('#roleSwitcher'))$('#roleSwitcher').innerHTML=`${roleInfo[app.role]?.label||'Ученик'} <svg><use href="#i-chevron"/></svg>`;if($('.profile-mini small'))$('.profile-mini small').textContent=roleInfo[app.role]?.profile||app.profile.role};
authModal=function(type='login'){app.authMode=type;const title=type==='register'?'Создать аккаунт':type==='forgot'?'Восстановление пароля':'Вход в DentAcademy';if(type==='register'){openModal(title,'<p>Клиент, слушатель, стажёр или врач может создать личный профиль. Врач сможет пройти оценку знаний и выбрать путь наставничества.</p><div class="field"><label>ФИО *</label><input id="authName" placeholder="Имя и фамилия"></div><div class="field"><label>Рабочая почта *</label><input id="authEmail" type="email" placeholder="name@clinic.kz"></div><div class="field"><label>Тип профиля</label><select id="authAccountType"><option value="learner">Клиент / слушатель / стажёр</option><option value="doctor">Врач-стоматолог</option></select></div><div class="field"><label>Клиника или учебная организация</label><input id="authClinic" placeholder="Название организации"></div><div class="field"><label>Специализация</label><input id="authSpecialty" placeholder="Например, терапевтическая стоматология"></div><div class="field"><label>Пароль *</label><input id="authPassword" type="password" minlength="8" placeholder="Не менее 8 символов"></div><p class="auth-note">Администратор и главный врач получают приглашение от организации; эти роли нельзя назначить при открытой регистрации.</p>','<button class="btn btn-outline" data-auth="login">У меня есть аккаунт</button><button class="btn btn-primary" data-action="auth-submit">Создать аккаунт</button>');return}if(type==='forgot'){openModal(title,'<p>Укажите почту аккаунта. В демо-версии ссылка не отправляется, здесь показан экран сценария восстановления.</p><div class="field"><label>Рабочая почта</label><input id="authEmail" type="email" placeholder="name@clinic.kz"></div>','<button class="btn btn-outline" data-auth="login">Назад ко входу</button><button class="btn btn-primary" data-action="auth-submit">Отправить ссылку</button>');return}openModal(title,'<p>Войдите в личный кабинет или создайте профиль ученика / врача.</p><div class="field"><label>Почта</label><input id="authEmail" type="email" placeholder="name@clinic.kz"></div><div class="field"><label>Пароль</label><input id="authPassword" type="password" placeholder="Пароль"></div><div class="auth-links"><a href="#" data-auth="forgot">Забыли пароль?</a><span>Демо-вход · локальный профиль</span></div>','<button class="btn btn-outline" data-auth="register">Регистрация</button><button class="btn btn-primary" data-action="auth-submit">Войти</button>')};
const _roleModalAction=modalForAction;
modalForAction=function(a,el){
 if(a==='auth-submit'){if($('#authEmail')&&!$('#authEmail').checkValidity()){toast('Проверьте адрес электронной почты');return}if(app.authMode==='forgot'){openModal('Восстановление пароля','<p>Демо-сценарий: запрос подготовлен. Письмо не отправлено; реальная отправка появится после подключения сервера.</p>');return}if($('#authName')){const name=$('#authName').value.trim(),email=$('#authEmail').value.trim(),password=$('#authPassword').value;if(!name||!email||password.length<8){toast('Заполните имя, почту и пароль не короче 8 символов');return}app.profile.name=name;app.profile.email=email;app.profile.specialty=$('#authSpecialty').value.trim()||'Стоматология';app.profile.organization=$('#authClinic').value.trim();const doctor=$('#authAccountType').value==='doctor';app.role='learner';app.profile.role=doctor?'Врач · обучение':'Ученик';app.doctorTrack=doctor?{status:'assessment'}:null;persistRole();closeModal();app.page='dashboard';renderPage();if(doctor)modalForAction('doctor-assessment');else toast('Учебный аккаунт создан на этом устройстве');return}const email=$('#authEmail')?.value.trim();if(email){app.profile.email=email;persistRole()}closeModal();app.page='dashboard';renderPage();toast('Открыт сохранённый демо-профиль');return}
 if(a==='switch-role'){openModal('Демо-профили','<p>Переключение показывает интерфейс разных аккаунтов. В реальной платформе доступы назначаются сервером и подтверждёнными учетными записями.</p><div class="role-grid"><button class="role-card" data-action="set-role" data-role-value="learner"><b>Ученик / врач</b><small>Курсы, тесты, вебинары, собственный прогресс</small></button><button class="role-card" data-action="doctor-assessment"><b>Врач: оценка знаний</b><small>Самостоятельная диагностика перед выбором пути</small></button><button class="role-card" data-action="set-role" data-role-value="mentor"><b>Врач-наставник</b><small>Ученики, обратная связь, заявки на практику и собственное обучение</small></button><button class="role-card" data-action="set-role" data-role-value="admin"><b>Администратор</b><small>Пользователи, клиники, контент, аналитика и исправления</small></button><button class="role-card" data-action="set-role" data-role-value="chief"><b>Главный врач</b><small>Все данные клиники, прогресс и решения по допускам</small></button><button class="btn btn-outline" data-action="open-registration">Создать аккаунт ученика / врача</button></div>');return}
 if(a==='open-registration'){authModal('register');return}
 if(a==='set-role'){const next=el?.dataset.roleValue;if(!roleInfo[next])return;app.role=next;app.profile.role=roleInfo[next].profile;persistRole();closeModal();app.page='dashboard';renderPage();toast(`Открыт демо-аккаунт: ${roleInfo[next].label}`);return}
 if(a==='doctor-assessment'){app.role='learner';app.doctorTrack={status:'assessment',score:null};persistRole();openModal('Определение уровня врача','<p>Ответьте на три демонстрационных вопроса. В реальной версии банк и проходной порог настраивает академия; практические навыки отдельно подтверждает наставник.</p><div class="field"><label>1. Какой первый шаг при подозрении на кариес?</label><select id="diag1"><option value="">Выберите ответ</option><option value="1">Собрать анамнез и провести клинический осмотр</option><option value="0">Сразу выбрать материал для реставрации</option></select></div><div class="field"><label>2. Что приоритетно при острой аллергической реакции?</label><select id="diag2"><option value="">Выберите ответ</option><option value="0">Продолжить лечение и наблюдать</option><option value="1">Остановить процедуру и действовать по протоколу неотложной помощи</option></select></div><div class="field"><label>3. Можно ли оценить готовность к ассистированию только тестом?</label><select id="diag3"><option value="">Выберите ответ</option><option value="0">Да, теста достаточно</option><option value="1">Нет, нужны подтверждённые практические навыки и оценка наставника</option></select></div><div class="status warning">Демо-порог для наставничества: 80% правильных ответов</div>','<button class="btn btn-outline" data-action="close-modal">Позже</button><button class="btn btn-primary" data-action="complete-doctor-assessment">Проверить ответы</button>');return}
 if(a==='complete-doctor-assessment'){const fields=[$('#diag1'),$('#diag2'),$('#diag3')];if(fields.some(f=>!f||f.value==='')){toast('Ответьте на все три вопроса');return}const score=Math.round(fields.reduce((sum,f)=>sum+(f.value==='1'?1:0),0)/fields.length*100),passed=score>=80;app.doctorTrack={status:passed?'passed':'learning',score,completedAt:new Date().toISOString()};persistRole();const resultBody=`<p>${passed?'Результат выше порога. Вы можете стать наставником и вести учеников или продолжить собственное обучение.':'Пока результата недостаточно для наставничества. Продолжите обучение, затем сможете пройти оценку повторно.'}</p><div class="stats-row">${stat('Результат',score+'%','Порог наставника: 80%','award')}${stat('Статус',passed?'Порог пройден':'Нужно обучение',passed?'Выберите дальнейший путь':'Доступна повторная оценка','check')}</div>`;const buttons=passed?'<button class="btn btn-outline" data-action="continue-doctor-learning">Продолжить обучение</button><button class="btn btn-primary" data-action="become-mentor">Стать наставником</button>':'<button class="btn btn-outline" data-action="continue-doctor-learning">Продолжить обучение</button><button class="btn btn-primary" data-action="doctor-assessment">Повторить оценку</button>';openModal(`Результат оценки · ${score}%`,resultBody,buttons);return}
 if(a==='continue-doctor-learning'){app.role='learner';app.profile.role='Врач · обучение';app.doctorTrack={...app.doctorTrack,status:'learning'};persistRole();closeModal();app.page='dashboard';renderPage();toast('Открыт путь обучения врача');return}
 if(a==='become-mentor'){app.role='mentor';app.profile.role='Врач · наставник';app.doctorTrack={...app.doctorTrack,status:'mentor'};persistRole();closeModal();app.page='dashboard';renderPage();toast('Открыт кабинет врача-наставника');return}
 _roleModalAction(a,el)
};
