Object.assign(daI18n['Қазақша'],{'Спасибо, вопрос получил. Посмотрю и отвечу в этом чате.':'Рақмет, сұрағыңызды алдым. Қарап шығып, осы чатта жауап беремін.','Здравствуйте! Можно обсудить мой план обучения и следующий практический шаг?':'Сәлеметсіз бе! Оқу жоспарым мен келесі практикалық қадамды талқылай аламыз ба?','Могу помочь структурировать тему: сформулируйте клинический вопрос, исходные данные и какой аспект нужно повторить. Для практических решений сверяйтесь с протоколом клиники и наставником.':'Тақырыпты жүйелеуге көмектесемін: клиникалық сұрақты, бастапқы деректерді және қай тұсты қайталау керегін жазыңыз. Практикалық шешімдер үшін клиника хаттамасы мен тәлімгерге сүйеніңіз.','Для учебного повторения разберите анамнез, осмотр, оценку риска и дополнительные методы диагностики. Затем сопоставьте находки с клиническим протоколом и обсудите неоднозначные случаи с наставником.':'Оқу мақсатында анамнезді, тексеруді, қауіпті бағалауды және қосымша диагностика әдістерін қарастырыңыз. Нәтижелерді клиникалық хаттамамен салыстырып, түсініксіз жағдайларды тәлімгермен талқылаңыз.','Повторите оценку состояния пациента, сбор анамнеза, противопоказания и алгоритм неотложной помощи клиники. Проверьте, где находится утверждённый протокол и кто отвечает за вызов экстренной помощи.':'Пациент жағдайын бағалауды, анамнез жинауды, қарсы көрсетілімдерді және клиниканың шұғыл көмек алгоритмін қайталаңыз. Бекітілген хаттаманың қайда тұрғанын және жедел жәрдем шақыруға кім жауапты екенін анықтаңыз.','Составьте план из коротких блоков: один урок, активное воспроизведение ключевых шагов, тест и повтор слабой темы через несколько дней. В академии можно сохранить урок и конспект в «Повторение».':'Қысқа бөлімдерден жоспар құрыңыз: бір сабақ, негізгі қадамдарды еске түсіру, тест және бірнеше күннен кейін қиын тақырыпты қайталау. Академияда сабақ пен конспектіні «Қайталау» бөліміне сақтауға болады.','Открыт демо-аккаунт:':'Демо-аккаунт ашылды:','Сохранено в подборку для повторения':'Қайталау жинағына сақталды','Файл в виде PDF для экспорта готов':'Экспортқа арналған PDF дайын','Рейтинг за квартал показан':'Тоқсандық рейтинг көрсетілді','Запись отменена':'Тіркелім жойылды','Открыто содержимое мини-модуля':'Шағын модуль мазмұны ашылды','Заявка ожидает проверки':'Өтінім тексеруді күтуде','Материал сохранён':'Материал сақталды','Пароль обновлён':'Құпиясөз жаңартылды','Изменения сохранены':'Өзгерістер сақталды'});
const daOriginalText=new WeakMap(),daOriginalAttrs=new WeakMap();
applyDaTranslations=function(root=document){const dict=daLanguage()?daI18n[daLanguage()]:null;const language=daLanguage();if(!root)return;if(root.nodeType===Node.TEXT_NODE){const node=root;if(!daOriginalText.has(node))daOriginalText.set(node,node.nodeValue);const original=daOriginalText.get(node);if(!language){node.nodeValue=original;return}let translated=original;const entries=Object.entries(dict).sort((a,b)=>b[0].length-a[0].length);for(const [from,to] of entries){if(from&&translated.includes(from))translated=translated.split(from).join(to)}node.nodeValue=translated;return}const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode())){if(!daOriginalText.has(node))daOriginalText.set(node,node.nodeValue);const original=daOriginalText.get(node);if(!language){node.nodeValue=original;continue}let translated=original;for(const [from,to] of Object.entries(dict).sort((a,b)=>b[0].length-a[0].length)){if(from&&translated.includes(from))translated=translated.split(from).join(to)}node.nodeValue=translated}root.querySelectorAll?.('input[placeholder],textarea[placeholder],[aria-label],[title]').forEach(el=>['placeholder','aria-label','title'].forEach(a=>{const value=el.getAttribute(a);if(!daOriginalAttrs.has(el))daOriginalAttrs.set(el,{});const attrs=daOriginalAttrs.get(el);if(!(a in attrs))attrs[a]=value;const original=attrs[a];el.setAttribute(a,language?(dict[original]||original):original)}));const role=$('#roleSwitcher');if(role){const original=role.dataset.originalRoleLabel||(role.dataset.originalRoleLabel=role.childNodes[0]?.nodeValue||'Ученик ');if(!language)role.childNodes[0].nodeValue=original;else role.childNodes[0].nodeValue=(language==='English'?(app.role==='mentor'?'Mentor':app.role==='admin'?'Administrator':app.role==='chief'?'Chief physician':'Learner'):(app.role==='mentor'?'Тәлімгер':app.role==='admin'?'Әкімші':app.role==='chief'?'Бас дәрігер':'Оқушы'))+' '}};
