function translateDaString(source,lang=daLanguage()){const dict=lang?daI18n[lang]:null;if(!dict)return source;const keys=Object.keys(dict).filter(Boolean).sort((a,b)=>b.length-a.length);if(!keys.length)return source;const matcher=new RegExp(keys.map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'g');return String(source).replace(matcher,key=>dict[key]||key)}
applyDaTranslations=function(root=document){const lang=daLanguage();if(!root)return;const translateNode=node=>{if(!daOriginalText.has(node))daOriginalText.set(node,node.nodeValue);const source=daOriginalText.get(node);node.nodeValue=translateDaString(source,lang)};if(root.nodeType===Node.TEXT_NODE){translateNode(root);return}const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode()))translateNode(node);root.querySelectorAll?.('input[placeholder],textarea[placeholder],[aria-label],[title]').forEach(el=>['placeholder','aria-label','title'].forEach(attr=>{const value=el.getAttribute(attr);if(!daOriginalAttrs.has(el))daOriginalAttrs.set(el,{});const attrs=daOriginalAttrs.get(el);if(!(attr in attrs))attrs[attr]=value;el.setAttribute(attr,translateDaString(attrs[attr],lang))}))};
const _toastBeforeI18n=toast;toast=function(message,...rest){return _toastBeforeI18n(translateDaString(String(message)),...rest)};
const _quickNotesBeforeI18n=renderQuickNotes;renderQuickNotes=function(...args){_quickNotesBeforeI18n(...args);applyDaTranslations($('#notesDrawerContent')||document)};
const _applyDaLanguageMeta=applyDaTranslations;applyDaTranslations=function(root=document){_applyDaLanguageMeta(root);const lang=app.profile?.language;document.documentElement.lang=lang==='English'?'en':lang==='Қазақша'?'kk':'ru';document.title=lang==='English'?'DentAcademy — Academy of Practical Dentistry':lang==='Қазақша'?'DentAcademy — Практикалық стоматология академиясы':'DentAcademy — Академия практической стоматологии';const role=$('#roleSwitcher');if(role){const label=lang==='English'?(app.role==='mentor'?'Mentor':app.role==='admin'?'Administrator':app.role==='chief'?'Chief physician':'Learner'):lang==='Қазақша'?(app.role==='mentor'?'Тәлімгер':app.role==='admin'?'Әкімші':app.role==='chief'?'Бас дәрігер':'Оқушы'):(roleInfo[app.role]?.label||'Ученик');role.childNodes[0].nodeValue=label+' '} };
if(typeof MutationObserver!=='undefined'&&!window.__daI18nObserver){window.__daI18nObserver=new MutationObserver(()=>{if(daLanguage())applyDaTranslations(document)});window.__daI18nObserver.observe(document.body,{childList:true,subtree:true})}
